import{_ as t}from"./chunks/zone-fees.D0x30c6y.js";import{_ as o,o as s,c as r,a5 as a}from"./chunks/framework.DukzBDYY.js";const g=JSON.parse('{"title":"Delivery Zones","description":"","frontmatter":{},"headers":[],"relativePath":"guides/zones.md","filePath":"guides/zones.md"}'),n={name:"guides/zones.md"};function d(i,e,h,l,c,p){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="delivery-zones" tabindex="-1">Delivery Zones <a class="header-anchor" href="#delivery-zones" aria-label="Permalink to &quot;Delivery Zones&quot;">​</a></h1><p>A schedule can have zones: the areas you deliver to, each with its own delivery days, order limit and fee. Addresses outside every zone get no slots, and the shipping method isn’t offered to them.</p><p><img src="'+t+'" alt="Slots for an Adelaide Hills address: only Thursday and Saturday can be chosen, the other days say Not in your area, and every slot is $4 extra"></p><p>There are two kinds, and a schedule can use both:</p><ul><li><strong>Postcode zones</strong>: a list of postcodes. Nothing else to install.</li><li><strong>Drawn zones</strong>: areas drawn on a map, with <a href="https://plugins.craftcms.com/geomaps" target="_blank" rel="noreferrer">Geo Maps</a> 1.4 or later. The free Lite edition is enough.</li></ul><h2 id="postcode-zones" tabindex="-1">Postcode zones <a class="header-anchor" href="#postcode-zones" aria-label="Permalink to &quot;Postcode zones&quot;">​</a></h2><p>In <strong>Delivery Slots → Schedules</strong>, open the shipping method and add rows under <strong>Postcode zones</strong>:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Shown on the run sheet and the order, such as “Inner east”</td></tr><tr><td><strong>Postcodes</strong></td><td>Separated by commas: exact (<code>5067</code>), ranges (<code>5000-5099</code>) or prefixes (<code>SW1*</code>). Case and spaces don’t matter</td></tr><tr><td><strong>Mon</strong> … <strong>Sun</strong></td><td>The days you deliver there. Leave them all unticked to use the schedule’s days</td></tr><tr><td><strong>Orders per slot</strong></td><td>A limit for this zone, on top of the slot’s own limit. Leave it blank for none</td></tr><tr><td><strong>Slot fee</strong></td><td>Added to the order’s shipping when a slot is chosen. Leave it blank for none</td></tr></tbody></table><p>For example:</p><table tabindex="0"><thead><tr><th>Name</th><th>Postcodes</th><th>Days</th><th>Orders per slot</th><th>Fee</th></tr></thead><tbody><tr><td>Inner east</td><td>5067, 5068, 5069</td><td>(schedule’s days)</td><td></td><td></td></tr><tr><td>Adelaide CBD</td><td>5000</td><td>Mon, Wed, Fri</td><td>6</td><td></td></tr><tr><td>Adelaide Hills</td><td>5150*, 5240-5250</td><td>Thu, Sat</td><td>4</td><td>$4</td></tr></tbody></table><p>Postcodes are only compared for addresses in your store’s country, set in <strong>Commerce → Store Management → Store → Store Location</strong>, so the same postcode abroad doesn’t match.</p><h2 id="drawn-zones" tabindex="-1">Drawn zones <a class="header-anchor" href="#drawn-zones" aria-label="Permalink to &quot;Drawn zones&quot;">​</a></h2><ol><li>Create a section for them, such as <strong>Delivery Zones</strong> (a channel, without URLs).</li><li>Give its entry type a Geo Maps field with <strong>Enable Drawing &amp; GeoJSON</strong> turned on.</li><li>Add an entry per zone, such as “Inner east”, and draw its area with the polygon tool, or upload a <code>.geojson</code> file.</li><li>In the schedule, add rows under <strong>Drawn zones</strong>: the entry, then the same days, limit and fee as postcode zones.</li></ol><p>Any entry with a drawn area can be a zone, so a store’s own delivery area works too. The same entries can price delivery in Commerce’s shipping rules; see below.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li><strong>Postcode zones are checked first</strong>, then drawn zones. Within each table, the first matching row is used: drag rows to put a small zone above a larger one around it.</li><li><strong>Addresses outside every zone get no slots, and the shipping method isn’t offered to them</strong>, once the customer has entered a postcode, or an address that can be placed on the map. Pickup methods usually have no zones, so they’re still offered.</li><li><strong>Days the zone doesn’t deliver</strong> show as <em>Not in your area</em>.</li><li><strong>Orders per slot</strong> counts only orders in the zone. With 4 for the Hills and 10 for the slot, the slot takes ten orders, at most four of them from the Hills.</li><li><strong>The fee</strong> is added as a shipping adjustment called <em>Delivery time</em>, before tax, so it’s taxed like the rest of the shipping. Show it with <code>slot.fee</code> in the picker.</li><li><strong>Addresses</strong> use the shipping address, or the estimated shipping address before checkout. For drawn zones, addresses with coordinates use them; others are looked up with Geo Maps’ map service.</li><li><strong>Renaming a postcode zone</strong> starts its orders-per-slot count again for orders that come in after the change.</li></ul><h2 id="prices-by-zone" tabindex="-1">Prices by zone <a class="header-anchor" href="#prices-by-zone" aria-label="Permalink to &quot;Prices by zone&quot;">​</a></h2><p>Slot fees are for extra charges on top of the shipping price. To price delivery by drawn zone or distance, use Geo Maps Pro’s <em>Delivery address is in zone</em> and <em>Delivery distance</em> conditions on your Commerce shipping rules; see <a href="https://plugins.geomaps.suprim.com.au/examples/delivery-zones" target="_blank" rel="noreferrer">Delivery Zones for Commerce</a> in the Geo Maps docs. Both work together: shipping rules set the price, zones set the days.</p><h2 id="without-zones" tabindex="-1">Without zones <a class="header-anchor" href="#without-zones" aria-label="Permalink to &quot;Without zones&quot;">​</a></h2><p>A schedule without zones gives every address its slots, wherever it is. Limit where the method is offered with a Commerce shipping zone on its rules, such as your country or state.</p><p>If Geo Maps is removed, drawn zones are kept but not used. Postcode zones keep working.</p>',21)])])}const y=o(n,[["render",d]]);export{g as __pageData,y as default};
